// ═══════════════════════════════════════════════════════════════════════════════
// ADMIN SISWA DELETE FUNCTIONS
// Fungsi untuk menghapus siswa per kelas dan semua siswa
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Hapus semua siswa dalam satu kelas
 */
window.deleteSiswaPerKelas = async function() {
  const kelasSelect = document.getElementById('filter-kelas-delete');
  if (!kelasSelect) {
    showCustomAlert('Error', 'Elemen filter kelas tidak ditemukan.', '❌');
    return;
  }

  const selectedKelas = kelasSelect.value;
  if (!selectedKelas || selectedKelas === '') {
    showCustomAlert('Pilih Kelas', 'Silakan pilih kelas terlebih dahulu.', '⚠️');
    return;
  }

  // Konfirmasi
  const confirmMsg = `Anda yakin ingin menghapus SEMUA siswa di kelas "${selectedKelas}"?\n\nTindakan ini TIDAK DAPAT DIBATALKAN!`;
  if (!confirm(confirmMsg)) {
    return;
  }

  // Double confirm
  const doubleConfirm = prompt(
    `Ketik nama kelas "${selectedKelas}" untuk mengkonfirmasi penghapusan:`,
    ''
  );
  if (doubleConfirm !== selectedKelas) {
    showCustomAlert('Dibatalkan', 'Penghapusan dibatalkan.', '❌');
    return;
  }

  showLoading('Menghapus siswa per kelas...');
  try {
    window.dbConnectFast && await window.dbConnectFast();

    // Ambil semua siswa
    const pesertaSnapshot = await db.ref('/peserta').once('value');
    const pesertaData = pesertaSnapshot.val() || {};

    // Filter siswa yang sesuai dengan kelas
    const siswaToDelete = [];
    for (const userId in pesertaData) {
      if (pesertaData[userId].kelas === selectedKelas) {
        siswaToDelete.push(userId);
      }
    }

    if (siswaToDelete.length === 0) {
      showCustomAlert('Tidak Ada Data', `Tidak ada siswa di kelas "${selectedKelas}".`, 'ℹ️');
      return;
    }

    // Hapus siswa satu per satu
    let deletedCount = 0;
    for (const userId of siswaToDelete) {
      try {
        await db.ref(`/peserta/${userId}`).remove();
        deletedCount++;
      } catch (err) {
        console.error(`Gagal menghapus siswa ${userId}:`, err);
      }
    }

    // Refresh UI
    loadAdminSiswa();
    updateFilterKelasDelete();

    showCustomAlert(
      'Berhasil',
      `${deletedCount} siswa dari kelas "${selectedKelas}" telah dihapus.`,
      '✅'
    );
  } catch (error) {
    console.error('Error deleting siswa per kelas:', error);
    showCustomAlert('Gagal', `Gagal menghapus siswa: ${error.message}`, '❌');
  } finally {
    window.dbDisconnect && window.dbDisconnect();
    hideLoading();
  }
};

/**
 * Hapus SEMUA siswa di sistem
 */
window.deleteSiswaSemuanya = async function() {
  // Triple confirm untuk keamanan
  const firstConfirm = confirm(
    'PERINGATAN: Anda akan menghapus SEMUA siswa di sistem!\n\nTindakan ini TIDAK DAPAT DIBATALKAN!\n\nLanjutkan?'
  );
  if (!firstConfirm) {
    return;
  }

  const secondConfirm = confirm(
    'Ini adalah konfirmasi KEDUA.\n\nYakin ingin menghapus SEMUA siswa?'
  );
  if (!secondConfirm) {
    return;
  }

  const thirdConfirm = prompt(
    'Ketik "HAPUS SEMUA SISWA" untuk mengkonfirmasi penghapusan permanen:',
    ''
  );
  if (thirdConfirm !== 'HAPUS SEMUA SISWA') {
    showCustomAlert('Dibatalkan', 'Penghapusan dibatalkan.', '❌');
    return;
  }

  showLoading('Menghapus semua siswa...');
  try {
    window.dbConnectFast && await window.dbConnectFast();

    // Ambil semua siswa
    const pesertaSnapshot = await db.ref('/peserta').once('value');
    const pesertaData = pesertaSnapshot.val() || {};

    const totalSiswa = Object.keys(pesertaData).length;

    if (totalSiswa === 0) {
      showCustomAlert('Tidak Ada Data', 'Tidak ada siswa untuk dihapus.', 'ℹ️');
      return;
    }

    // Hapus semua siswa
    let deletedCount = 0;
    for (const userId in pesertaData) {
      try {
        await db.ref(`/peserta/${userId}`).remove();
        deletedCount++;
      } catch (err) {
        console.error(`Gagal menghapus siswa ${userId}:`, err);
      }
    }

    // Refresh UI
    loadAdminSiswa();
    updateFilterKelasDelete();

    showCustomAlert(
      'Berhasil',
      `${deletedCount} siswa telah dihapus dari sistem.`,
      '✅'
    );
  } catch (error) {
    console.error('Error deleting all siswa:', error);
    showCustomAlert('Gagal', `Gagal menghapus siswa: ${error.message}`, '❌');
  } finally {
    window.dbDisconnect && window.dbDisconnect();
    hideLoading();
  }
};

/**
 * Update filter kelas dropdown setelah perubahan data
 */
window.updateFilterKelasDelete = async function() {
  const filterSelect = document.getElementById('filter-kelas-delete');
  if (!filterSelect) return;

  try {
    window.dbConnectFast && await window.dbConnectFast();

    const pesertaSnapshot = await db.ref('/peserta').once('value');
    const pesertaData = pesertaSnapshot.val() || {};

    // Ambil daftar kelas unik
    const kelasList = [...new Set(
      Object.values(pesertaData).map(p => p.kelas)
    )].sort();

    // Update dropdown
    filterSelect.innerHTML = '<option value="">-- Pilih Kelas --</option>' +
      kelasList.map(kelas => `<option value="${kelas}">${kelas}</option>`).join('');
  } catch (error) {
    console.error('Error updating filter kelas:', error);
  } finally {
    window.dbDisconnect && window.dbDisconnect();
  }
};

/**
 * Initialize filter kelas dropdown saat halaman siswa dimuat
 */
window.initFilterKelasDelete = async function() {
  const filterSelect = document.getElementById('filter-kelas-delete');
  if (!filterSelect) return;

  try {
    window.dbConnectFast && await window.dbConnectFast();

    const pesertaSnapshot = await db.ref('/peserta').once('value');
    const pesertaData = pesertaSnapshot.val() || {};

    // Ambil daftar kelas unik
    const kelasList = [...new Set(
      Object.values(pesertaData).map(p => p.kelas)
    )].sort();

    // Populate dropdown
    filterSelect.innerHTML = '<option value="">-- Pilih Kelas --</option>' +
      kelasList.map(kelas => `<option value="${kelas}">${kelas}</option>`).join('');
  } catch (error) {
    console.error('Error initializing filter kelas:', error);
  } finally {
    window.dbDisconnect && window.dbDisconnect();
  }
};

// Initialize saat tab siswa dibuka
document.addEventListener('DOMContentLoaded', function() {
  // Hook ke tab siswa
  const siswaTab = document.querySelector('[data-tab="tab-siswa"]');
  if (siswaTab) {
    siswaTab.addEventListener('click', function() {
      setTimeout(() => {
        initFilterKelasDelete();
      }, 100);
    });
  }
});
